planContingencia:{name:'Plan de Contingencia',fac:'neutral',art:'📋',type:'directiva',pos:'na',cost:1,rar:'PC',text:'Mira las 2 cartas superiores de tu mazo. Pon una en la parte superior y la otra en el fondo. Timeline Bonus — Si tienes 4 o más cartas en tu Timeline: Roba 1 carta.',tlb:{cond:{k:'tlMin',v:4},eff:{t:'draw',n:1}},effect:{t:'peekDrawTL',min:4}},
